CREATE TABLE categories (name VARCHAR(60) PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products (id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, category VARCHAR(60) NOT NULL, description TEXT NOT NULL, image VARCHAR(1000) NOT NULL, price DECIMAL(12,2) NOT NULL, compare_price DECIMAL(12,2) NULL, unit VARCHAR(50) NOT NULL, in_stock BOOLEAN NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 2147483647, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category) REFERENCES categories(name), CHECK(price>0), CHECK(compare_price IS NULL OR compare_price>price)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE daily_counters (day DATE PRIMARY KEY, last_number INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE orders (id CHAR(36) PRIMARY KEY, request_id CHAR(36) NOT NULL UNIQUE, order_reference VARCHAR(40) NOT NULL UNIQUE, full_name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, address VARCHAR(500) NOT NULL, city VARCHAR(100) NOT NULL, notes TEXT NOT NULL, total DECIMAL(14,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'new', email_status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id CHAR(36) NOT NULL, product_id CHAR(36) NULL, product_name VARCHAR(100) NOT NULL, unit VARCHAR(50) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY, hits INT NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB;
